class Solution {
  public long maxTotalValue(int[] nums, int k) {
    int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
    for (int x : nums) {
      min = Math.min(min, x);
      max = Math.max(max, x);
    }
    // the whole array has the widest range; pick it k times
    return (long) k * (max - min);
  }
}
